      c.fillStyle=tint||'#5fd0ff'; c.beginPath(); c.ellipse(hx-3,hy-2,2.6,2,0,0,7); c.fill(); c.beginPath(); c.ellipse(hx+3,hy-2,2.6,2,0,0,7); c.fill();
