      c.fillStyle='#d9dee6'; c.beginPath(); c.moveTo(hx-r*0.9,hy-r-0.5); c.quadraticCurveTo(hx,hy-r*2.5,hx+r*0.9,hy-r-0.5); c.closePath(); c.fill();
