/* the achievements window: one big scrollable window, hub / Stickseum / Crown Envoy / Beaconfall */
function achWin(T){
  var w=document.getElementById('ffpAch');
  if(!w){ w=document.createElement('div'); w.id='ffpAch'; w.innerHTML='<div class="w"><div class="hd"><b></b><button type="button" class="x">✕</button></div><div class="L"></div></div>'; document.body.appendChild(w);
    w.addEventListener('click',function(e){ if(e.target===w) w.classList.remove('on'); });
    w.querySelector('.x').onclick=function(){ w.classList.remove('on'); };
    document.addEventListener('keydown',function(e){ if(e.key==='Escape') w.classList.remove('on'); }); }
  w.querySelector('.hd b').textContent=T.achBtn; w.querySelector('.x').setAttribute('aria-label',T.close);
  return w;
}
/* ---- 게임 통계: 게임·허브 어디서 열어도 같은 카드이고, 게임 안에서 열면 카드 아래에 그 게임의 통계가 붙어요.
   게임은 FFProfile.gameStats('게임id', function(box, ctx){ ... }) 로 자기 통계를 넣어요(box 에 HTML 문자열이나 노드를 그리거나 반환해도 돼요). ctx={sb,uid,own,data,lang,esc,game}.
   게임 id 는 FFPresence.game(주소로 정해져요)이고, FFProfile.open 의 o.game 으로 바꿀 수 있어요. 훅이 없으면 도전과제와 플레이 횟수만 보여요. ---- */
function gameId(o){ return (o&&o.game)||(window.FFPresence&&window.FFPresence.game)||''; }
async function gameSection(el, sb, uid, d, o, T, own){
  var box=el.querySelector('.G'), g=gameId(o); if(!box||!g) return;
  var info=null; GAMES.forEach(function(x){ if(x.id===g) info=x; }); var hook=(o&&o.stats)||GS[g];
  if(!info&&!hook) return;
  var st=(d.profile&&d.profile.stats)||{}, ids=(d.ids&&d.ids[g])||{}, A=d.ach&&d.ach[g], have=Object.keys(ids).length;
  if(g==='stickseum'&&Array.isArray(st.ach)) have=Math.max(have, st.ach.length);
  if(A) have=Math.max(have, A[0]||0);
  var total=A?A[1]:0, plays=d.played&&d.played[g], name=(o&&o.gameName)||(info&&info.name)||g;
  var h='<h5>'+esc((info?info.icon+' ':'')+fmt(T.gstat,name))+'</h5>';
  if(!hook){
  if(total>0) h+='<div class="gr"><span>'+esc(T.gAch)+'</span><b>'+have+' / '+total+'</b></div><div class="gb"><u style="width:'+Math.min(100,100*have/total).toFixed(1)+'%"></u></div>';
  else if(have>0) h+='<div class="gr"><span>'+esc(T.gAch)+'</span><b>'+have+'</b></div>';
  if(plays) h+='<div class="gr"><span>'+esc(T.gPlays)+'</span><b>'+esc(fmt(T.gTimes,plays))+'</b></div>';
  }
  box.innerHTML=h+'<div class="gx"></div>';
  if(!hook) return;
  var gx=box.querySelector('.gx');
  try{ var r=await hook(gx, {sb:sb, uid:uid, own:own, data:d, lang:lang(o), esc:esc, game:g});
    if(typeof r==='string') gx.insertAdjacentHTML('beforeend', r); else if(r&&r.nodeType) gx.appendChild(r); }catch(e){}
}
function inGame(o){ if(o&&o.noDeco!=null) return !!o.noDeco; if(window.FF_INGAME) return true; return /\/(Stickseum|CrownEnvoy|BEACONFALL|IslandTrade)-[^\/]*\.html/i.test(location.pathname); }
async function open(sb, uid, o){
  var T=L[lang(o)], el=modal(T), cv=el.querySelector('canvas'), msg=el.querySelector('.m');
  el.querySelector('.s').textContent=T.save; el.querySelector('.c').textContent=T.close; var dcb=el.querySelector('.dc'); dcb.textContent=T.deco; dcb.style.display='none'; el.querySelector('.D').className='D'; el.querySelector('.D').innerHTML=''; el.querySelector('.k').textContent=T.link; el.querySelector('.k').style.display='none';
  var acb=el.querySelector('.ac'); acb.textContent=T.achBtn; acb.style.display='none'; el.scrollTop=0; el.querySelector('.hn').style.display='none'; el.querySelector('.G').innerHTML='';
  el.style.display='flex'; cv.style.display='none'; msg.textContent=T.loading;
  try{ var d=await fetchData(sb, uid); await draw(cv, d, o); cv.style.display=''; msg.textContent=''; }
  catch(e){ msg.textContent=T.fail; return; }
  var own=false;
  try{ var s=await sb.auth.getSession(), me=s&&s.data&&s.data.session&&s.data.session.user;
    if(me&&me.id===uid){ own=true; var h=await syncHub(sb, uid, d); if(h){ d.ids=d.ids||{}; d.ids.hub={}; h.forEach(function(k){ d.ids.hub[k]=1; }); rateCache=null; }
      if(inGame(o)){ }
      else if(editOk){ dcb.style.display=''; dcb.onclick=function(){ var P=el.querySelector('.D'); if(P.classList.toggle('on')) decoPanel(el, sb, uid, d, cv, o); }; }
      else { var hn=el.querySelector('.hn'); hn.innerHTML=esc(T.hubOnly)+'<a href="'+HUBSITE+'">'+esc(T.hubGo)+'</a>'; hn.style.display='block'; } } }catch(e){}
  gameSection(el, sb, uid, d, o, T, own);
  acb.style.display=''; acb.onclick=async function(){ var w=achWin(T), box=w.querySelector('.L'); box.innerHTML='<div class="n">'+esc(T.loading)+'</div>'; box.scrollTop=0; w.classList.add('on');
    try{ await list(box, sb, d, o); }catch(e){ box.innerHTML='<div class="n">'+esc(T.fail)+'</div>'; } };
  if(o&&o.openAch) acb.click();
  var lk=el.querySelector('.k'), un=d.profile&&d.profile.username; lk.style.display=un?'':'none';
  lk.onclick=function(){ var u='https://frenchfries777mc.github.io/games/?card='+encodeURIComponent(un);
    var done=function(){ lk.textContent='✓ '+T.copied; setTimeout(function(){ lk.textContent=T.link; },2000); };
    if(navigator.share&&/Mobi|Android|iPad|iPhone/i.test(navigator.userAgent)){ navigator.share({title:'Frenchfries777',url:u}).catch(function(){}); return; }
    var manual=function(){ var i=document.createElement('input'); i.value=u; i.readOnly=true; i.style.cssText='margin-left:8px;max-width:100%;padding:6px 8px;border-radius:8px;border:1px solid #333;background:#10131b;color:#eef0f5;font:inherit'; lk.parentNode.insertBefore(i,lk.nextSibling); i.focus(); i.select(); };
    try{ navigator.clipboard.writeText(u).then(done,manual); }catch(e){ manual(); } };
}
/* the account button's small round photo when no profile photo is picked: the game character, drawn like on the card */
async function avatarDataUrl(sb, uid){ try{ var p=await sb.from('profiles').select('stats').eq('id',uid).single(), av=(p&&!p.error&&p.data&&p.data.stats&&p.data.stats.avatar)||{}, im=av.ext?await loadImg(ext(av.ext)):null, a=document.createElement('canvas'); a.width=a.height=96; drawAvatar(a, av, im); return a.toDataURL('image/png'); }catch(e){ return null; } }
window.FFProfile={t2lock:t2lock, avatarDataUrl:avatarDataUrl, open:open, gameStats:function(game, fn){ if(typeof fn==='function') GS[game]=fn; }, canEdit:function(){ return editOk; }, hubUrl:HUBSITE, markPlayed:markPlayed, setAchievements:setAchievements, draw:draw, fetchData:fetchData, games:GAMES, characters:EXT_CHARS, catalog:catalog, syncHub:syncHub, deco:DECO, titles:TITLES, avatars:AVATARS, avatarUrl:avatarUrl};
